/**
 * Host-only source driver for live binding capacity. It keeps no AST/event log.
 * Generated bytes are access-site fixtures, not a runnable Scheme program.
 * Reader completeness, literal identity storage, capture analysis and execution
 * remain separate proofs; quoted datum spelling is counted but not interned here.
 */
import { BindingResolver } from "./resolver.ts";
import { SourceTokens, type Token } from "./source-tokens.ts";

export const PREDEFINED = [
  "+",
  "-",
  "*",
  "quotient",
  "remainder",
  "=",
  "<",
  ">",
  "<=",
  ">=",
  "cons",
  "car",
  "cdr",
  "list",
  "eq?",
  "not",
  "null?",
  "pair?",
  "number?",
  "boolean?",
  "symbol?",
  "procedure?",
  "string?",
  "char?",
  "eof-object?",
  "write",
  "display",
  "write-char",
  "newline",
  "read-char",
];
const BINDER_LIMIT = 64, STAGED_NONE = 0xffff;
const syntax = new Set([
  "quote",
  "if",
  "lambda",
  "define",
  "set!",
  "begin",
  "let",
  "let*",
  "letrec",
  "cond",
  "and",
  "or",
  "else",
  "=>",
]);
const isLiteral = (t: Token) =>
  t.kind === "string" || /^[+-]?\d+$/.test(t.text) ||
  ["#t", "#f"].includes(t.text) || t.text.startsWith("#\\");

export function inspectSources(parts: readonly string[]) {
  const resolver = new BindingResolver(PREDEFINED);
  let procedure = 0, nextProcedure = 0, depth = 0, maxDepth = 0;
  const staged = new Uint16Array(BINDER_LIMIT).fill(STAGED_NONE);
  let stagedTop = 0,
    stagedCount = 0,
    peakBinders = 0,
    tokensFetched = 0,
    quotedAtoms = 0;
  const fail = (t: Token, why: string): never => {
    resolver.abort();
    throw new Error(`${t.part}:${t.offset}: ${why}`);
  };
  const name = (t: Token) => {
    if (t.kind !== "atom" || isLiteral(t) || syntax.has(t.text)) {
      fail(t, "expected binding name");
    }
    return t.text;
  };
  function enter() {
    resolver.enterScope();
  }
  function leave() {
    resolver.leaveScope();
  }
  function newProcedure(body: () => void) {
    const saved = procedure;
    if (++nextProcedure > 65535) {
      resolver.abort();
      throw new Error("procedure key capacity");
    }
    procedure = nextProcedure;
    body();
    procedure = saved;
  }
  function withList(input: SourceTokens, action: () => void) {
    input.expect("(");
    if (++depth > 32) {
      resolver.abort();
      throw new Error("source nesting capacity");
    }
    maxDepth = Math.max(maxDepth, depth);
    action();
    input.expect(")");
    depth--;
  }
  function datum(input: SourceTokens) {
    const token = input.peek();
    if (token.text === "(") {
      withList(input, () => {
        while (input.peek().text !== ")") datum(input);
      });
    } else if (token.text === "'") {
      input.take();
      datum(input);
    } else {
      if (token.kind === "eof" || token.text === ")") {
        fail(token, "unfinished datum");
      }
      input.take();
      quotedAtoms++;
    }
  }
  function formals(input: SourceTokens) {
    withList(input, () => {
      while (input.peek().text !== ")") resolver.declare(name(input.take()));
    });
  }
  function body(input: SourceTokens) {
    let leading = true, expressions = 0;
    while (input.peek().text !== ")") {
      if (input.peek().kind === "eof") fail(input.peek(), "unfinished body");
      const wasDefinition = expression(input, false, () => {
        if (leading) resolver.seal();
        leading = false;
      }, () => leading);
      if (!wasDefinition) expressions++;
    }
    if (expressions === 0) fail(input.peek(), "body requires an expression");
  }
  function definition(input: SourceTokens) {
    if (input.peek().text === "(") {
      input.expect("(");
      const binder = input.take();
      resolver.declare(name(binder));
      newProcedure(() => {
        enter();
        while (input.peek().text !== ")") resolver.declare(name(input.take()));
        input.expect(")");
        body(input);
        leave();
      });
    } else {
      resolver.declare(name(input.take()));
      expression(input);
    }
  }
  function pinned(input: SourceTokens): number {
    const token = input.take();
    const spelling = name(token);
    if (stagedTop === BINDER_LIMIT) fail(token, "pending binder capacity");
    const id = resolver.stage(spelling);
    const slot = stagedTop++;
    staged[slot] = id;
    stagedCount++;
    peakBinders = Math.max(peakBinders, stagedCount);
    return slot;
  }
  function takeStaged(slot: number): [number, boolean] {
    if (slot < 0 || slot >= stagedTop || staged[slot] === STAGED_NONE) {
      throw new Error("staged binder invariant");
    }
    const id = staged[slot];
    staged[slot] = STAGED_NONE;
    stagedCount--;
    while (stagedTop > 0 && staged[stagedTop - 1] === STAGED_NONE) {
      stagedTop--;
    }
    for (let i = 0; i < stagedTop; i++) {
      if (staged[i] === id) return [id, true];
    }
    return [id, false];
  }
  function consumeBinder(slot: number) {
    const [id, retain] = takeStaged(slot);
    const spelling = resolver.names.spelling(id);
    resolver.declare(spelling);
    resolver.unstage(id, retain);
    resolver.releaseUnusedName(id);
  }
  function letForm(input: SourceTokens, kind: string) {
    let recursiveName: number | undefined;
    if (kind === "let" && input.peek().text !== "(") {
      recursiveName = pinned(input);
    }
    let scopes = 0;
    const mark = stagedTop;
    if (kind === "letrec") {
      enter();
      scopes++;
    }
    withList(input, () => {
      while (input.peek().text !== ")") {
        withList(input, () => {
          if (kind === "letrec") {
            resolver.declare(name(input.take()));
            expression(input);
          } else if (kind === "let*") {
            const slot = pinned(input);
            expression(input);
            enter();
            scopes++;
            consumeBinder(slot);
          } else {
            pinned(input);
            expression(input);
          }
        });
        if (kind === "let*" && input.peek().text !== ")") resolver.seal();
      }
    });
    if (kind === "letrec") {
      resolver.seal();
      resolver.reopenDefinitions();
    } else if (kind === "let*") {
      if (scopes === 0) {
        enter();
        scopes++;
      }
    } else {
      if (recursiveName !== undefined) {
        enter();
        scopes++;
        consumeBinder(recursiveName);
        resolver.seal();
      }
      enter();
      scopes++;
      for (let slot = mark; slot < stagedTop; slot++) consumeBinder(slot);
    }
    if (recursiveName === undefined) body(input);
    else newProcedure(() => body(input));
    while (scopes-- > 0) leave();
  }
  function expression(
    input: SourceTokens,
    top = false,
    onValue = () => {},
    definitionsAllowed = () => false,
  ): boolean {
    const first = input.peek();
    if (first.text === "'") {
      onValue();
      input.take();
      datum(input);
      return false;
    }
    if (first.text !== "(") {
      onValue();
      const token = input.take();
      if (token.kind === "eof" || token.text === ")") {
        fail(token, "expected expression");
      }
      if (!isLiteral(token)) resolver.use(name(token), token, procedure);
      return false;
    }
    let isDefinition = false;
    withList(input, () => {
      const head = input.peek();
      if (head.text === "define") {
        if (!top && !definitionsAllowed()) {
          fail(head, "definition outside leading region");
        }
        input.take();
        definition(input);
        isDefinition = true;
        return;
      }
      onValue();
      if (head.text === "quote") {
        input.take();
        datum(input);
      } else if (head.text === "lambda") {
        input.take();
        newProcedure(() => {
          enter();
          formals(input);
          body(input);
          leave();
        });
      } else if (["let", "let*", "letrec"].includes(head.text)) {
        input.take();
        letForm(input, head.text);
      } else if (head.text === "set!") {
        input.take();
        const target = input.take();
        resolver.use(name(target), target, procedure);
        expression(input);
      } else if (head.text === "if") {
        input.take();
        expression(input);
        expression(input);
        if (input.peek().text !== ")") expression(input);
      } else if (head.text === "cond") {
        input.take();
        while (input.peek().text !== ")") {
          withList(input, () => {
            if (input.peek().text === "else") input.take();
            else expression(input);
            let results = 0;
            while (input.peek().text !== ")") {
              expression(input);
              results++;
            }
            if (results === 0) fail(head, "cond result required");
          });
        }
      } else if (["begin", "and", "or"].includes(head.text)) {
        input.take();
        while (input.peek().text !== ")") {
          expression(input, top && head.text === "begin");
        }
      } else {
        expression(input);
        while (input.peek().text !== ")") expression(input);
      }
    });
    return isDefinition;
  }
  try {
    for (let part = 0; part < parts.length; part++) {
      const input = new SourceTokens(parts[part], part);
      while (input.peek().kind !== "eof") expression(input, true);
      tokensFetched += input.fetched;
    }
    resolver.finish();
  } catch (error) {
    resolver.abort();
    throw error;
  }
  return {
    resolver,
    sourceBytes: parts.reduce((n, p) => n + p.length, 0),
    tokensFetched,
    maxSourceDepth: maxDepth,
    procedures: nextProcedure,
    quotedAtoms,
    pendingBinderBytes: BINDER_LIMIT * 2,
    peakPendingBinders: peakBinders,
  };
}
